package com.markethub.admin;
import com.markethub.order.*; import com.markethub.vendor.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service public class AdminOrderService{
 private final OrderRepository orders;private final OrderItemRepository items;private final VendorRepository vendors;public AdminOrderService(OrderRepository o,OrderItemRepository i,VendorRepository v){orders=o;items=i;vendors=v;}
 @Transactional(readOnly=true) public AdminOrderPageResponse list(OrderStatus status,Long customerId,int page,int size){Specification<Order>s=Specification.where(null);if(status!=null)s=s.and((r,q,c)->c.equal(r.get("status"),status));if(customerId!=null)s=s.and((r,q,c)->c.equal(r.get("customer").get("id"),customerId));return AdminOrderPageResponse.from(orders.findAll(s,PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending().and(Sort.by("id").descending()))));}
 @Transactional(readOnly=true) public AdminOrderDetailResponse get(Long id){Order o=orders.findById(id).orElseThrow(()->new AdminNotFoundException("Order not found"));List<OrderItem> all=items.findByOrderIdOrderByIdAsc(id);Map<Long,Vendor> map=vendors.findAllById(all.stream().map(OrderItem::getVendorId).distinct().toList()).stream().collect(Collectors.toMap(Vendor::getId,Function.identity()));return AdminOrderDetailResponse.from(o,all,map);}}